func isMirror(a, b *TreeNode) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	return a.Val == b.Val && isMirror(a.Left, b.Right) && isMirror(a.Right, b.Left)
}

func isSymmetric(root *TreeNode) bool {
	return isMirror(root, root)
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  public boolean isSymmetric(TreeNode root) {
    return isMirror(root, root);
  }

  private boolean isMirror(TreeNode a, TreeNode b) {
    if (a == null && b == null) {
      return true;
    }
    if (a == null || b == null) {
      return false;
    }
    return a.val == b.val && isMirror(a.left, b.right) && isMirror(a.right, b.left);
  }
}

class Solution:
    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        def is_mirror(a, b):
            if a is None and b is None:
                return True
            if a is None or b is None:
                return False
            return a.val == b.val and is_mirror(a.left, b.right) and is_mirror(a.right, b.left)

        return is_mirror(root, root)

impl Solution {
  fn is_mirror(a: &Option<Box<TreeNode>>, b: &Option<Box<TreeNode>>) -> bool {
    match (a, b) {
      (None, None) => true,
      (Some(x), Some(y)) => {
        x.val == y.val
          && Solution::is_mirror(&x.left, &y.right)
          && Solution::is_mirror(&x.right, &y.left)
      }
      _ => false,
    }
  }

  pub fn is_symmetric(root: Option<Box<TreeNode>>) -> bool {
    Solution::is_mirror(&root, &root)
  }
}

const isSymmetric = (root: TreeNode | null): boolean => {
  const isMirror = (a: TreeNode | null, b: TreeNode | null): boolean => {
    if (a === null && b === null) return true;
    if (a === null || b === null) return false;
    return a.val === b.val && isMirror(a.left, b.right) && isMirror(a.right, b.left);
  };
  return isMirror(root, root);
};
